"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["43786"],{12666(e,t,s){s.d(t,{Ay:()=>i,RM:()=>a});var r=s(74848),o=s(28453),n=s(66422);let a=[];function h(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"whats-wrong-with-brothels-brothels-are-the-source-of-chinese-culture",children:"What's Wrong with Brothels? Brothels Are the Source of Chinese Culture!"})}),"\n",(0,r.jsxs)(t.blockquote,{children:["\n",(0,r.jsx)(t.p,{children:"2006/3/9 10:00:26"}),"\n"]}),"\n",(0,r.jsxs)("div",{style:{textAlign:"center"},children:[(0,r.jsx)("img",{src:(0,n.Ay)("/img/essays/brothels/1.jpeg")}),(0,r.jsx)("br",{}),(0,r.jsx)("br",{})]}),"\n",(0,r.jsx)(t.p,{children:'Today I happened to see a post claiming that Chinese cinema has become "brothel-ized" and therefore debased. But what\'s wrong with brothels? The cream of Chinese culture all came from brothels \u2014 brothels are the source of Chinese culture! Today\'s garbage Chinese films don\'t even deserve to be associated with brothels. Don\'t assume that just because China\'s greatest novel is related to the "Red Chamber" [Dream of the Red Chamber] you can look down on the "Green Chamber" [brothels]. The person who wrote the Red Chamber was certainly connected to the Green Chamber \u2014 without brothels, there would be no Red Chamber.'}),"\n",(0,r.jsx)(t.p,{children:"Never mind how Liu Rushi brought the two great literary alliance leaders of the late Ming and early Qing to their knees, and how centuries later, one of the last century's most preeminent Chinese scholars still wrote a biographical study of this woman who came from the brothels. Never mind how many masterpieces of the Tang and Song were written in brothels, or how much of China's classical music and painting was produced there. Never mind how many of China's most beloved love stories have been continuously manufactured in brothels over the centuries. Just consider: nowadays everything has been \"culture-ified\" \u2014 sex culture, tea culture, wine culture, this culture and that culture \u2014 so why can't brothels have their own cultural moment?"}),"\n",(0,r.jsx)(t.p,{children:"Brothels encompassed virtually everything China proudly claims as culture \u2014 sex culture, tea culture, wine culture \u2014 which of these wasn't magnified and glorified in brothels? Poetry, lyrics, songs, prose, political essays \u2014 which could have flourished without passing through the brothels? Look at the one who wrote \"to see a thousand miles further\" [Wang Zhihuan] \u2014 when he went to a higher floor of the brothel with two other famous men, he turned beet red because the courtesans there weren't singing his work. This proves that brothels were indeed the wellspring of culture, and even more so of inspiration."}),"\n",(0,r.jsx)(t.p,{children:'The disappearance of brothels accompanied the degradation of an entire civilization. Only the most vulgar people shamelessly and absolutely equate brothels with sex trade. True brothels were mostly about things beyond sex. Just as fine wine needs a fine cellar, the brothel was that cellar \u2014 what was aged inside was Maotai and Wuliangye. With the brothel \u2014 that "cellar" slandered as a "kiln" \u2014 Chinese culture was able to defeat time and remain sublimely fragrant.'}),"\n",(0,r.jsx)(t.p,{children:"Nowadays, one old thing after another is being restored \u2014 so why can't brothels be restored? Beyond the laughable reasons of so-called morality and such, the most critical point is that people today simply aren't worthy of brothels. Tell me: is there anyone today who is worthy of the brothels the way Li Bai, Du Fu, or Su Shi were? Is there anyone today writing verses worthy of the brothels, like \"Ten years' Yangzhou dream \u2014 a fleeting sojourn\"?"}),"\n",(0,r.jsx)(t.p,{children:"Brothels \u2014 the source of Chinese culture, the historical dream of Chinese civilization!"})]})}function i(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},82439(e,t,s){s.r(t),s.d(t,{metadata:()=>r,default:()=>d,frontMatter:()=>h,contentTitle:()=>i,toc:()=>u,assets:()=>l});var r=JSON.parse('{"id":"timeline/essays/brothels","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/essays/brothels.md","sourceDirName":"timeline/essays","slug":"/timeline/essays/brothels","permalink":"/en/timeline/essays/brothels","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"brothels","title":"","hide_table_of_contents":true,"sidebar_label":"What\'s Wrong with Brothels \u2014 Brothels Are the Source of Chinese Culture! (2006/3/9 10:00:26)"},"sidebar":"timelineSidebar","previous":{"title":"Girls, Use Every Organ on Your Body to Fully Consume Men! (2006/3/8 18:41:04)","permalink":"/en/timeline/essays/consumemen"},"next":{"title":"Even Hu Shi Is Now a Master of Chinese Classics \u2014 The Absurd Finally Has Something More Absurd! (2006/3/9 13:01:36)","permalink":"/en/timeline/essays/hushi"}}'),o=s(74848),n=s(28453),a=s(12666);let h={id:"brothels",title:"",hide_table_of_contents:!0,sidebar_label:"What's Wrong with Brothels \u2014 Brothels Are the Source of Chinese Culture! (2006/3/9 10:00:26)"},i,l={},u=[...a.RM];function c(e){return(0,o.jsx)(a.Ay,{})}function d(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},28453(e,t,s){s.d(t,{R:()=>a,x:()=>h});var r=s(96540);let o={},n=r.createContext(o);function a(e){let t=r.useContext(n);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),r.createElement(n.Provider,{value:t},e.children)}}}]);